import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788344355000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Four environment variables; only the first is required.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>RUSTPAD_URL</code></td><td>yes</td><td>Base URL of the instance, e.g. <code>https://rustpad.example.net</code></td></tr><tr><td><code>RUSTPAD_READ_ONLY</code></td><td>no</td><td><code>true</code> registers only the read tools</td></tr><tr><td><code>RUSTPAD_INSECURE_TLS</code></td><td>no</td><td><code>true</code> accepts self-signed certificates (scoped to this connection only)</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>false</code> replaces the approval dialog with the two-call token</td></tr></tbody></table><h2 id="one-url-for-everything" tabindex="-1">One URL for everything <a class="header-anchor" href="#one-url-for-everything" aria-label="Permalink to “One URL for everything”">​</a></h2><p><code>RUSTPAD_URL</code> serves three purposes: the HTTP API (<code>/api/text</code>, <code>/api/stats</code>), the collaboration WebSocket (<code>http</code>/<code>https</code> is mapped to <code>ws</code>/<code>wss</code>), and the share links the tools return (<code>&lt;RUSTPAD_URL&gt;/#&lt;pad-id&gt;</code>). If your instance sits behind a reverse proxy, that proxy must forward WebSocket upgrades on <code>/api/socket/…</code>.</p><p>The URL is validated on start: only <code>http:</code>/<code>https:</code>, no embedded credentials, no query string or fragment. A plain-<code>http</code> URL to a non-loopback host starts with a warning — everything, including full pad content, would travel unencrypted. A malformed URL exits instead of limping along.</p><h2 id="boolean-semantics" tabindex="-1">Boolean semantics <a class="header-anchor" href="#boolean-semantics" aria-label="Permalink to “Boolean semantics”">​</a></h2><p>The two prefixed booleans are parsed in opposite directions, because their failure modes are not symmetric.</p><p><code>RUSTPAD_READ_ONLY</code> is a <strong>protection</strong>, so it is read leniently: <code>true</code>, <code>TRUE</code>, <code>1</code> and <code>yes</code> all switch it on, surrounding whitespace and all. Read strictly, <code>RUSTPAD_READ_ONLY=1</code> would register all five write tools against an instance the operator meant to protect, and nothing anywhere would report it.</p><p><code>RUSTPAD_INSECURE_TLS</code> <strong>removes</strong> one, so it compares against exactly the string <code>true</code>. <code>True</code> or <code>1</code> count as false there, which leaves certificate validation on — the harmless way to be wrong. The server prints a banner on start when insecure-TLS mode is actually active.</p><p><code>ELICITATION</code> is the exception, in both directions: it is case-insensitive, and a value that is neither <code>true</code> nor <code>false</code> <strong>stops the server</strong> instead of falling back. It is the only one of the three that defaults to <em>on</em>, so failing open on a typo would leave the dialog running while the operator believed it was off.</p><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p>Guarded tools — <code>set_document</code> on a non-empty pad, <code>replace_in_document</code> across more than one match — ask a person through MCP elicitation before they act. <code>ELICITATION=false</code> takes them to the two-call token instead. It does not remove the guard; there is no setting in which a guarded call goes unannounced.</p><p>The variable deliberately carries no <code>RUSTPAD_</code> prefix, which means it reaches every MCP server in the same environment. <a href="/guide/approval">Asking a person</a> explains what that costs and what makes it visible.</p><h2 id="ephemerality" tabindex="-1">Ephemerality <a class="header-anchor" href="#ephemerality" aria-label="Permalink to “Ephemerality”">​</a></h2><p>Rustpad keeps documents in memory; they are lost when the server restarts and after 24 hours without an open connection. If you want pads to survive, run the Rustpad instance itself with <code>SQLITE_URI</code> (see the <a href="https://github.com/ekzhang/rustpad#configuration" target="_blank" rel="noreferrer">Rustpad README</a>) — nothing changes on the rustpad-mcp side.</p><h2 id="limits-worth-knowing" tabindex="-1">Limits worth knowing <a class="header-anchor" href="#limits-worth-knowing" aria-label="Permalink to “Limits worth knowing”">​</a></h2><ul><li>Documents are capped at 256 KiB by Rustpad itself; the server checks before sending and refuses edits that would exceed it.</li><li>Tool results are budgeted to ~200 000 characters; a larger pad is truncated with an explicit notice rather than silently cut.</li><li>Every network wait has a wall-clock timeout (15–20 s); a hostile or hung upstream costs a failed tool call, never a hung server.</li></ul><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. <code>RUSTPAD_ALLOW_TOOLS</code> and <code>RUSTPAD_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">RUSTPAD_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">RUSTPAD_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">get_document,append_to_document</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">RUSTPAD_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">set_document</span></span></code></pre></div><p>Why bother, when all eight work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, eight is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_x</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of five:</p><p><code>get_document</code>, <code>get_document_info</code>, <code>create_document</code>, <code>set_document</code>, <code>append_to_document</code>.</p><p>It composes — naming a tool alongside it puts that one back, and <code>RUSTPAD_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>RUSTPAD_ALLOW_TOOLS</code> decides what is in; <code>RUSTPAD_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>RUSTPAD_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, and <code>RUSTPAD_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>RUSTPAD_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};